62. 			if err != nil {
63. 				log.Warnf(ctx, "unable to get spark version for cluster %s, err: %s", task.ExistingClusterId, err.Error())
64. 				return false
65. 			}
66. 
67. 			if lowerThanExpectedVersion(ctx, version) {
68. 				return true
69. 			}
70. 		}
71. 	}
72. 
73. 	return false
74. }
