81. 
82. 	if parts[1][0] == 'x' { // treat versions like 13.x as the very latest minor (13.99)
83. 		parts[1] = "99"
84. 	}
85. 	v := "v" + parts[0] + "." + parts[1]
86. 	return semver.Compare(v, "v13.1") < 0
